#!/bin/bash
# foamy-kit 0.9.0 1fe704c34ceb0cc6cc9e3e6bc6e8a0e19d0508e479725049ac523714949319d9 — do not edit; change foamy-kit and run sync
# Checks that this plugin's foamy-kit files are unedited copies.
# Generated by foamy-kit sync.sh. To change a kit file, change it in
# foamy-kit and run `sync.sh <this plugin>`; never edit it here.
set -euo pipefail

root=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
lock="$root/foamy-kit.lock"
failures=0
fail() {
  echo "kit-check: $*" >&2
  failures=$((failures + 1))
}

[[ -f $lock ]] || {
  echo "kit-check: missing foamy-kit.lock" >&2
  exit 1
}
version=$(awk '$1 == "version" { print $2; exit }' "$lock")
[[ -n $version ]] || {
  echo "kit-check: foamy-kit.lock has no version" >&2
  exit 1
}

stamp_re='^(//|#) foamy-kit ([^ ]+) ([0-9a-f]{64}) '
declare -A listed=()

while read -r hash rel; do
  [[ $hash =~ ^[0-9a-f]{64}$ ]] || continue
  if [[ $rel == /* || /$rel/ == */../* || /$rel/ == */./* || $rel == *//* || $rel == *\\* ]] \
    || [[ $rel != kit/?* && $rel != tests/kit-check.sh && $rel != REVIEW.md && $rel != rust-toolchain.toml &&
      $rel != .github/workflows/verify-native.yml && $rel != .github/workflows/checks.yml &&
      $rel != .oxlintrc.json && $rel != .qmlformat.ini && $rel != mise.toml && $rel != ruff.toml &&
      $rel != tests/validate.sh ]]; then
    fail "foamy-kit.lock lists $rel, which is not a path foamy-kit owns"
    continue
  fi
  listed[$rel]=1
  file="$root/$rel"
  if [[ -L $file || ! -f $file ]]; then
    fail "$rel is missing or not a regular file"
    continue
  fi
  stamp_line=0
  for n in 1 2; do
    if [[ $(sed -n "${n}p" "$file") =~ $stamp_re ]]; then
      stamp_line=$n
      stamp_version=${BASH_REMATCH[2]}
      stamp_hash=${BASH_REMATCH[3]}
      break
    fi
  done
  if ((stamp_line == 0)); then
    # Notices and REVIEW.md are copied verbatim, without a stamp line.
    actual=$(sha256sum <"$file" | cut -d' ' -f1)
    [[ $actual == "$hash" ]] || fail "$rel was edited (hash differs from foamy-kit.lock)"
    continue
  fi
  actual=$(sed "${stamp_line}d" "$file" | sha256sum | cut -d' ' -f1)
  [[ $stamp_version == "$version" ]] || fail "$rel is stamped $stamp_version, lock says $version"
  [[ $actual == "$stamp_hash" ]] || fail "$rel was edited locally (body no longer matches its stamp)"
  [[ $stamp_hash == "$hash" ]] || fail "$rel stamp differs from foamy-kit.lock"
done <"$lock"

if [[ -d $root/kit ]]; then
  while IFS= read -r -d '' file; do
    rel=${file#"$root"/}
    [[ -n ${listed[$rel]:-} ]] || fail "$rel is not part of foamy-kit (remove it or add it to foamy-kit)"
  done < <(find "$root/kit" \( -type f -o -type l \) -print0)
fi

# AGENTS.md is the plugin's, apart from one block sync manages: the pointer
# that makes review agents follow the shared REVIEW.md.
agents_expected=$(
  cat <<'FOAMY_AGENTS_BLOCK'
<!-- foamy-kit review: begin; managed by foamy-kit sync.sh, edit outside this block -->
## Code review

Follow [REVIEW.md](REVIEW.md) when reviewing or preparing a change. It is the
shared Foamy review standard, synced from foamy-kit. The rest of this file
adds repository-specific rules.
<!-- foamy-kit review: end -->
FOAMY_AGENTS_BLOCK
)
agents_begin=${agents_expected%%$'\n'*}
agents_end=${agents_expected##*$'\n'}
agents="$root/AGENTS.md"
if [[ -L $agents || ! -f $agents ]]; then
  fail "AGENTS.md is missing or not a regular file (run foamy-kit sync.sh)"
else
  agents_marks=$(grep -c -F '<!-- foamy-kit review:' "$agents" || true)
  agents_actual=$(awk -v b="$agents_begin" -v e="$agents_end" '$0 == b { on = 1 } on { print } on && $0 == e { exit }' "$agents")
  [[ $agents_marks == 2 && $agents_actual == "$agents_expected" ]] \
    || fail "AGENTS.md lacks the current foamy-kit review block (run foamy-kit sync.sh)"
fi

# Native helpers (FoamyNative): bin/<arch>/<binary> must match <crate>/native.pin,
# be static ELF executables for their arch, and be built from the current
# sources (the pin's source hash: the crate, kit/rust, and Cargo.toml,
# Cargo.lock and rust-toolchain.toml at the root; kit files without their
# stamp line; see foamy-kit tools/foamykit.py).
unstamped() {
  local n line
  for n in 1 2; do
    line=$(sed -n "${n}p" "$1" | tr -d '\000')
    if [[ $line =~ $stamp_re ]]; then
      sed "${n}d" "$1"
      return
    fi
  done
  cat "$1"
}
source_hash() {
  local crate=$1 file
  {
    find "$root/$crate" -path "$root/$crate/target" -prune -o -type f ! -path "$root/$crate/native.pin" -print0
    if [[ -d $root/kit/rust ]]; then find "$root/kit/rust" -type f -print0; fi
    for file in Cargo.lock Cargo.toml rust-toolchain.toml; do
      if [[ -f $root/$file && ! -L $root/$file ]]; then printf '%s\0' "$root/$file"; fi
    done
  } | while IFS= read -r -d '' file; do printf '%s\0' "${file#"$root"/}"; done | LC_ALL=C sort -z -u \
    | while IFS= read -r -d '' file; do
      printf '%s  %s\n' "$(unstamped "$root/$file" | sha256sum | cut -d' ' -f1)" "$file"
    done | sha256sum | cut -d' ' -f1
}
components=$(awk '$1 == "components" { print $2; exit }' "$lock")
native=0
[[ ,$components, == *,FoamyNative,* ]] && native=1
pins=()
while IFS= read -r -d '' pin; do pins+=("$pin"); done < <(
  find "$root" -mindepth 2 -maxdepth 2 -name native.pin -type f ! -path "$root/.*" -print0 | LC_ALL=C sort -z
)
((native == 0 || ${#pins[@]} > 0)) || fail "FoamyNative is synced but no <crate>/native.pin exists (run kit/native/build-native.sh .)"
native_bins=()
if ((${#pins[@]} > 0)) && ! command -v file >/dev/null; then
  fail "file(1) is needed to check the native helper binaries"
fi
for pin in "${pins[@]}"; do
  crate=${pin%/native.pin}
  crate=${crate##*/}
  value() { awk -v key="$1" '$1 == key && NF == 2 { print $2; exit }' "$pin"; }
  ((native == 1)) || fail "$crate/native.pin exists but FoamyNative is not synced"
  [[ $(value crate) == "$crate" ]] || fail "$crate/native.pin names crate '$(value crate)', expected '$crate'"
  binary=$(value binary)
  if [[ ! $binary =~ ^[A-Za-z0-9][A-Za-z0-9._-]*$ ]]; then
    fail "$crate/native.pin has no valid binary name"
    continue
  fi
  for arch in x86_64 aarch64; do
    rel="bin/$arch/$binary"
    file="$root/$rel"
    expected=$(awk -v rel="$rel" '$2 == rel && length($1) == 64 && $1 ~ /^[0-9a-f]+$/ { print $1; exit }' "$pin")
    if [[ -z $expected ]]; then
      fail "$crate/native.pin has no checksum for $rel"
      continue
    fi
    if [[ -L $file || ! -f $file ]]; then
      fail "$rel is missing or not a regular file"
      continue
    fi
    [[ -x $file ]] || fail "$rel is not executable"
    [[ $(sha256sum <"$file" | cut -d' ' -f1) == "$expected" ]] || fail "$rel checksum differs from native.pin"
    case $arch in x86_64) want="x86-64" ;; aarch64) want="ARM aarch64" ;; esac
    info=$(file -b -- "$file" 2>/dev/null || true)
    [[ $info == *"ELF 64-bit LSB"* && $info == *"$want"* ]] || fail "$rel is not a 64-bit $arch ELF: $info"
    [[ $info == *"statically linked"* || $info == *"static-pie linked"* ]] || fail "$rel is not statically linked: $info"
  done
  if [[ $(source_hash "$crate") != "$(value source)" ]]; then
    fail "$binary is stale: $crate/, kit/rust, Cargo.toml, Cargo.lock or rust-toolchain.toml changed since it was built (run kit/native/build-native.sh .)"
  elif [[ $(value kit) != "$version" ]]; then
    # Fresh binaries: the pin's kit line names the kit they match; sync refreshes it.
    fail "$crate/native.pin says kit $(value kit), foamy-kit.lock says $version (run foamy-kit sync.sh, which refreshes it)"
  fi
  native_bins+=("$binary")
done

# Third-party notices: the build writes THIRD_PARTY_NOTICES.md (the licenses
# and copyright notices of the code linked into the binaries) with the
# binaries, and `build-native.sh . --verify` regenerates and compares it.
# Here, without cargo: it exists and names each pin's source hash and checksums.
notices="$root/THIRD_PARTY_NOTICES.md"
if ((${#pins[@]} > 0)); then
  if [[ -L $notices || ! -f $notices ]]; then
    fail "THIRD_PARTY_NOTICES.md is missing (run kit/native/build-native.sh .)"
  else
    [[ $(head -n 1 "$notices") == "# Third-party notices: native helpers" ]] \
      || fail "THIRD_PARTY_NOTICES.md was not written by kit/native/build-native.sh"
    for pin in "${pins[@]}"; do
      crate=${pin%/native.pin}
      crate=${crate##*/}
      pin_source=$(awk '$1 == "source" && NF == 2 { print $2; exit }' "$pin")
      toolchain=$(awk '$1 == "toolchain" && NF == 2 { print $2; exit }' "$pin")
      matches=1
      grep -qxF -- "- \`$crate/native.pin\`: source \`$pin_source\`, toolchain $toolchain" "$notices" || matches=0
      while read -r hash rel; do
        grep -qxF -- "- \`$rel\`: sha256 \`$hash\`" "$notices" || matches=0
      done < <(awk 'NF == 2 && length($1) == 64 && $1 ~ /^[0-9a-f]+$/ { print }' "$pin")
      ((matches == 1)) \
        || fail "THIRD_PARTY_NOTICES.md does not match $crate/native.pin (run kit/native/build-native.sh .)"
    done
  fi
fi

# A cargo target dir inside the plugin (cargo run without CARGO_TARGET_DIR)
# is only a warning: the shell watches plugin folders, so remove it.
while IFS= read -r -d '' tag; do
  dir=${tag%/CACHEDIR.TAG}
  echo "kit-check: warning: ${dir#"$root"/}/ is a cargo target dir inside the plugin; remove it and export CARGO_TARGET_DIR=~/.cache/foamy-native/<plugin> before any cargo command" >&2
done < <(find "$root" -mindepth 2 -maxdepth 3 -path '*/target/CACHEDIR.TAG' -type f ! -path "$root/.*" -print0 2>/dev/null)

if ((failures > 0)); then
  echo "kit-check: $failures problem(s); run foamy-kit sync.sh to restore the kit files" >&2
  exit 1
fi
echo "kit-check: foamy-kit $version OK (${#listed[@]} files${native_bins[*]:+; native: ${native_bins[*]} x86_64, aarch64})"
